var t=`0416-dublin-coddle`;var i=`world-0416`;var o=`IE`;var s=`northern-europe`;var a=4;var r=78;var d={en:`Dublin Coddle`,ua:`Дублінський кодл`};var g={en:`A traditional dish from Ireland, centered on bacon, yellow onion, potato, fresh pork sausage. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Ірландія. Основні складники: бекон, жовта цибуля, картопля, сира свиняча ковбаса. Домашній варіант із кількостями продуктів за етапами приготування.`};var l=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`bacon`,160,`g`],[`yellow-onion`,250,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 65 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 65 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:65,i:[[`potato`,700,`g`],[`fresh-pork-sausage`,650,`g`],[`chicken-stock`,900,`ml`],[`thyme`,3,`sprig`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`parsley`,20,`g`],[`ground-black-pepper`,null,`to_taste`]]}];var u={slug:t,id:i,country:`IE`,region:s,servings:4,minutes:78,title:d,text:g,steps:l};export{o as country,u as default,i as id,r as minutes,s as region,a as servings,t as slug,l as steps,g as text,d as title};